-- 09-games: uploaded workbook snapshot. Run entire file, then Write Changes.
-- Save pending edits and take a backup first. No BEGIN/COMMIT needed in DB Browser.
-- Identical reruns are safe; changed existing records are never overwritten.
PRAGMA foreign_keys=ON;
SAVEPOINT afl_season_9;
CREATE TEMP TABLE afl_season_import_stamp(effective_at TEXT NOT NULL);
CREATE TEMP TABLE afl_season_9_0 AS SELECT id, season_id, legacy_game_number, stage, regular_week, playoff_round, home_team_id, away_team_id, status, kickoff_at_utc, kickoff_source_local, kickoff_timezone, network, weather_text, venue_name, is_neutral_site, field_branding_key, settings_version_id, engine_version, started_at, ended_at FROM games WHERE 0;
CREATE TEMP TABLE afl_season_9_1 AS SELECT game_id, version, phase, period, seconds_remaining, home_score, away_score, possession_team_id, down, distance, ball_on, drive_start, previous_ball_on, home_timeouts, away_timeouts, opening_receiving_team_id, pending_conversion_team_id, pending_action, overtime_period, overtime_phase, overtime_first_receiving_team_id, last_play_id FROM game_state WHERE 0;
CREATE TEMP TABLE afl_season_9_guard(ok INTEGER);
CREATE TEMP TRIGGER afl_season_9_check BEFORE INSERT ON afl_season_9_guard
BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM leagues WHERE id='36c6e53f-7be2-5a94-84a8-0df871aae9fd' AND name='AFL') THEN RAISE(ROLLBACK,'Missing AFL league.') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM seasons WHERE id='97808f43-a0d5-5251-bf8d-fae1643c8258' AND league_id='36c6e53f-7be2-5a94-84a8-0df871aae9fd') THEN RAISE(ROLLBACK,'Import season (05) first.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_season_9_0 i LEFT JOIN team_seasons h ON h.season_id=i.season_id AND h.team_id=i.home_team_id LEFT JOIN team_seasons a ON a.season_id=i.season_id AND a.team_id=i.away_team_id WHERE h.id IS NULL OR a.id IS NULL) THEN RAISE(ROLLBACK,'Import home/away team-season details (06) first.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_season_9_0 i JOIN games t ON t.id=i.id WHERE t.season_id IS NOT i.season_id OR t.legacy_game_number IS NOT i.legacy_game_number OR t.stage IS NOT i.stage OR t.regular_week IS NOT i.regular_week OR t.playoff_round IS NOT i.playoff_round OR t.home_team_id IS NOT i.home_team_id OR t.away_team_id IS NOT i.away_team_id OR t.status IS NOT i.status OR t.kickoff_at_utc IS NOT i.kickoff_at_utc OR t.kickoff_source_local IS NOT i.kickoff_source_local OR t.kickoff_timezone IS NOT i.kickoff_timezone OR t.network IS NOT i.network OR t.weather_text IS NOT i.weather_text OR t.venue_name IS NOT i.venue_name OR t.is_neutral_site IS NOT i.is_neutral_site OR t.field_branding_key IS NOT i.field_branding_key OR t.settings_version_id IS NOT i.settings_version_id OR t.engine_version IS NOT i.engine_version OR t.started_at IS NOT i.started_at OR t.ended_at IS NOT i.ended_at) THEN RAISE(ROLLBACK,'games: existing ID has different data; no records overwritten.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_season_9_0 i JOIN games t ON t.season_id=i.season_id AND t.legacy_game_number=i.legacy_game_number WHERE t.id<>i.id) THEN RAISE(ROLLBACK,'games: natural key belongs to another ID.') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM leagues WHERE id='36c6e53f-7be2-5a94-84a8-0df871aae9fd' AND name='AFL') THEN RAISE(ROLLBACK,'Missing AFL league.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_season_9_1 i JOIN game_state t ON t.game_id=i.game_id WHERE t.version IS NOT i.version OR t.phase IS NOT i.phase OR t.period IS NOT i.period OR t.seconds_remaining IS NOT i.seconds_remaining OR t.home_score IS NOT i.home_score OR t.away_score IS NOT i.away_score OR t.possession_team_id IS NOT i.possession_team_id OR t.down IS NOT i.down OR t.distance IS NOT i.distance OR t.ball_on IS NOT i.ball_on OR t.drive_start IS NOT i.drive_start OR t.previous_ball_on IS NOT i.previous_ball_on OR t.home_timeouts IS NOT i.home_timeouts OR t.away_timeouts IS NOT i.away_timeouts OR t.opening_receiving_team_id IS NOT i.opening_receiving_team_id OR t.pending_conversion_team_id IS NOT i.pending_conversion_team_id OR t.pending_action IS NOT i.pending_action OR t.overtime_period IS NOT i.overtime_period OR t.overtime_phase IS NOT i.overtime_phase OR t.overtime_first_receiving_team_id IS NOT i.overtime_first_receiving_team_id OR t.last_play_id IS NOT i.last_play_id) THEN RAISE(ROLLBACK,'game_state: existing ID has different data; no records overwritten.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_season_9_1 i JOIN game_state t ON t.game_id=i.game_id WHERE t.game_id<>i.game_id) THEN RAISE(ROLLBACK,'game_state: natural key belongs to another ID.') END;
END;
DROP TRIGGER afl_season_9_check;
DROP TABLE afl_season_9_guard;
DROP TABLE afl_season_9_0;
DROP TABLE afl_season_9_1;
DROP TABLE afl_season_import_stamp;
RELEASE SAVEPOINT afl_season_9;
