INSERT INTO games (id, season_id, legacy_game_number, stage, regular_week, playoff_round, home_team_id, away_team_id, status, kickoff_at_utc, kickoff_source_local, kickoff_timezone, network, weather_text, venue_name, is_neutral_site, field_branding_key, settings_version_id, engine_version, started_at, ended_at) SELECT i.id, i.season_id, i.legacy_game_number, i.stage, i.regular_week, i.playoff_round, i.home_team_id, i.away_team_id, i.status, i.kickoff_at_utc, i.kickoff_source_local, i.kickoff_timezone, i.network, i.weather_text, i.venue_name, i.is_neutral_site, i.field_branding_key, i.settings_version_id, i.engine_version, i.started_at, i.ended_at FROM afl_season_9_0 i WHERE NOT EXISTS(SELECT 1 FROM games t WHERE t.id=i.id) ON CONFLICT(id) DO NOTHING;
INSERT INTO game_state (game_id, version, phase, period, seconds_remaining, home_score, away_score, possession_team_id, down, distance, ball_on, drive_start, previous_ball_on, home_timeouts, away_timeouts, opening_receiving_team_id, pending_conversion_team_id, pending_action, overtime_period, overtime_phase, overtime_first_receiving_team_id, last_play_id) SELECT i.game_id, i.version, i.phase, i.period, i.seconds_remaining, i.home_score, i.away_score, i.possession_team_id, i.down, i.distance, i.ball_on, i.drive_start, i.previous_ball_on, i.home_timeouts, i.away_timeouts, i.opening_receiving_team_id, i.pending_conversion_team_id, i.pending_action, i.overtime_period, i.overtime_phase, i.overtime_first_receiving_team_id, i.last_play_id FROM afl_season_9_1 i WHERE NOT EXISTS(SELECT 1 FROM game_state t WHERE t.game_id=i.game_id) ON CONFLICT(game_id) DO NOTHING;
